#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    static char buf[200005];
    scanf("%s", buf);
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        g[a].push_back(b);
        g[b].push_back(a);
    }
    int LOG = 1;
    while ((1 << LOG) <= n) LOG++;  // bit_length(n)
    vector<int> parent(n, 0), depth(n, 0), mask(n, 0);
    mask[0] = 1 << (buf[0] - 'a');
    vector<int> st = {0};
    while (!st.empty()) {
        int v = st.back();
        st.pop_back();
        for (int w : g[v]) {
            if (w == parent[v]) continue;
            parent[w] = v;
            depth[w] = depth[v] + 1;
            mask[w] = mask[v] ^ (1 << (buf[w] - 'a'));
            st.push_back(w);
        }
    }
    vector<vector<int>> up(LOG, vector<int>(n));
    up[0] = parent;
    for (int j = 1; j < LOG; j++)
        for (int i = 0; i < n; i++) up[j][i] = up[j - 1][up[j - 1][i]];
    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) swap(a, b);
        int delta = depth[a] - depth[b];
        for (int j = 0; j < LOG; j++)
            if (delta >> j & 1) a = up[j][a];
        if (a == b) return a;
        for (int j = LOG - 1; j >= 0; j--)
            if (up[j][a] != up[j][b]) a = up[j][a], b = up[j][b];
        return parent[a];
    };
    string out;
    out.reserve(2 * q);
    for (int i = 0; i < q; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        int v = lca(a, b);
        int parity = mask[a] ^ mask[b] ^ (1 << (buf[v] - 'a'));
        out += __builtin_popcount(parity) <= 1 ? '1' : '0';
        out += '\n';
    }
    fputs(out.c_str(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        String labels = next();
        int[] head = new int[n], nxt = new int[2 * (n - 1)], to = new int[2 * (n - 1)];
        Arrays.fill(head, -1);
        int ec = 0;
        for (int i = 0; i < n - 1; i++) {
            int a = nextInt(), b = nextInt();
            to[ec] = b; nxt[ec] = head[a]; head[a] = ec++;
            to[ec] = a; nxt[ec] = head[b]; head[b] = ec++;
        }
        int log = 32 - Integer.numberOfLeadingZeros(n);  // bit_length(n)
        int[] parent = new int[n], depth = new int[n], mask = new int[n];
        mask[0] = 1 << (labels.charAt(0) - 'a');
        int[] stack = new int[n];
        int sp = 0;
        stack[sp++] = 0;
        while (sp > 0) {
            int v = stack[--sp];
            for (int e = head[v]; e != -1; e = nxt[e]) {
                int w = to[e];
                if (w == parent[v]) continue;
                parent[w] = v;
                depth[w] = depth[v] + 1;
                mask[w] = mask[v] ^ (1 << (labels.charAt(w) - 'a'));
                stack[sp++] = w;
            }
        }
        int[][] up = new int[log][];
        up[0] = parent;
        for (int j = 1; j < log; j++) {
            up[j] = new int[n];
            for (int i = 0; i < n; i++) up[j][i] = up[j - 1][up[j - 1][i]];
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int a = nextInt(), b = nextInt();
            int x = a, y = b;
            if (depth[x] < depth[y]) { int t = x; x = y; y = t; }
            int delta = depth[x] - depth[y];
            for (int j = 0; j < log; j++) if ((delta >> j & 1) != 0) x = up[j][x];
            int v;
            if (x == y) v = x;
            else {
                for (int j = log - 1; j >= 0; j--)
                    if (up[j][x] != up[j][y]) { x = up[j][x]; y = up[j][y]; }
                v = parent[x];
            }
            int parity = mask[a] ^ mask[b] ^ (1 << (labels.charAt(v) - 'a'));
            sb.append(Integer.bitCount(parity) <= 1 ? '1' : '0').append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"math/bits"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n, q := readInt(), readInt()
	labels := readToken()
	g := make([][]int, n)
	for i := 0; i < n-1; i++ {
		a, b := readInt(), readInt()
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}
	log := bits.Len(uint(n))
	parent := make([]int, n)
	depth := make([]int, n)
	mask := make([]int, n)
	mask[0] = 1 << (labels[0] - 'a')
	st := []int{0}
	for len(st) > 0 {
		v := st[len(st)-1]
		st = st[:len(st)-1]
		for _, w := range g[v] {
			if w == parent[v] {
				continue
			}
			parent[w] = v
			depth[w] = depth[v] + 1
			mask[w] = mask[v] ^ (1 << (labels[w] - 'a'))
			st = append(st, w)
		}
	}
	up := make([][]int, log)
	up[0] = parent
	for j := 1; j < log; j++ {
		up[j] = make([]int, n)
		for i := 0; i < n; i++ {
			up[j][i] = up[j-1][up[j-1][i]]
		}
	}
	lca := func(a, b int) int {
		if depth[a] < depth[b] {
			a, b = b, a
		}
		delta := depth[a] - depth[b]
		for j := 0; j < log; j++ {
			if delta>>j&1 == 1 {
				a = up[j][a]
			}
		}
		if a == b {
			return a
		}
		for j := log - 1; j >= 0; j-- {
			if up[j][a] != up[j][b] {
				a, b = up[j][a], up[j][b]
			}
		}
		return parent[a]
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < q; i++ {
		a, b := readInt(), readInt()
		v := lca(a, b)
		parity := mask[a] ^ mask[b] ^ (1 << (labels[v] - 'a'))
		if bits.OnesCount(uint(parity)) <= 1 {
			w.WriteString("1\n")
		} else {
			w.WriteString("0\n")
		}
	}
}
